<?php
require __DIR__ . '/includes/bootstrap.php';
$pageTitle = 'COVID-19 Data';
$db = db_or_error();
$rows = $db ? $db->query('SELECT country_name,total_cases,total_deaths,recoveries,vaccination_count,data_source,reported_at FROM covid_statistics ORDER BY total_cases DESC')->fetchAll() : [];
require __DIR__ . '/includes/header.php';
?>
<main class="container page-space"><div class="page-intro"><span class="eyebrow">TRANSPARENT BY DESIGN</span><h1>COVID-19 <span class="accent">data</span></h1><p class="lead">Explore the dataset available to this academic demonstration. Missing values are shown as unavailable, never as zero.</p></div>
<?php if (!$db): ?><div class="alert error">Statistics are temporarily unavailable because the database could not be reached. Start MySQL and check the setup instructions.</div><?php elseif (!$rows): ?><div class="empty-state"><span>⌁</span><h2>No data has been loaded</h2><p>Import the database schema and clearly labeled demonstration seed to add the report snapshot.</p></div><?php else: ?>
<section class="panel data-panel"><div class="table-toolbar"><div><span class="eyebrow">COUNTRY SNAPSHOT</span><h2>Available reported figures</h2></div><label class="search-box"><span aria-hidden="true">⌕</span><input id="country-search" type="search" placeholder="Search country" aria-label="Search by country"></label></div>
<div class="table-scroll"><table id="stats-table"><caption class="sr-only">Country statistics; figures are demonstration data from the STQA report mock-up</caption><thead><tr><th scope="col">Country</th><th scope="col"><button class="sort-button" data-sort="total_cases" type="button">Reported cases <span>↕</span></button></th><th scope="col"><button class="sort-button" data-sort="total_deaths" type="button">Deaths <span>↕</span></button></th><th scope="col">Discharged</th><th scope="col">Vaccination doses</th><th scope="col">Reporting date</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><span class="country-cell"><span class="country-flag">IN</span><strong><?= h($row['country_name']) ?></strong></span></td><td data-value="<?= h((string)$row['total_cases']) ?>"><?= number_format((int)$row['total_cases']) ?></td><td data-value="<?= $row['total_deaths'] === null ? '' : h((string)$row['total_deaths']) ?>"><?= $row['total_deaths'] === null ? '<span class="muted">Not reported</span>' : number_format((int)$row['total_deaths']) ?></td><td><?= $row['recoveries'] === null ? '<span class="muted">Not reported</span>' : number_format((int)$row['recoveries']) ?></td><td><?= $row['vaccination_count'] === null ? '<span class="muted">Not reported</span>' : number_format((int)$row['vaccination_count']) ?></td><td><?= $row['reported_at'] ? h($row['reported_at']) : '<span class="muted">Undated</span>' ?></td></tr><?php endforeach; ?></tbody></table></div><p id="empty-search" class="empty-search" hidden>No country matches your search.</p>
<div class="data-note"><span class="note-icon">i</span><div><strong>Dataset note</strong><p>Source: the undated India dashboard mock-up embedded in the supplied STQA report. It lists 44,998,520 reported cases, 1,824 active hospitalizations, 44,646,120 discharged, and 2,206,750,000 doses administered. The report does not provide a death count or reporting date. These values are for demonstrating the interface only; they are not current official statistics.</p></div></div></section>
<?php endif; ?><section class="callout slim"><div><span class="eyebrow">DATA QUALITY</span><h2>Want a current public dataset?</h2><p>This starter project works offline. Replace the clearly labeled demo seed with a dated dataset from an official source before presenting statistics as current.</p></div><a class="button ghost" href="https://covid19dashboard.mohfw.gov.in/" target="_blank" rel="noopener noreferrer">MoHFW data portal ↗</a></section></main>
<script>
const search=document.querySelector('#country-search'),body=document.querySelector('#stats-table tbody'),empty=document.querySelector('#empty-search');search?.addEventListener('input',()=>{let visible=0;for(const row of body.rows){const show=row.cells[0].innerText.toLowerCase().includes(search.value.trim().toLowerCase());row.hidden=!show;if(show)visible++}empty.hidden=visible!==0});
document.querySelectorAll('.sort-button').forEach(button=>button.addEventListener('click',()=>{const col=button.dataset.sort==='total_cases'?1:2,rows=[...body.rows],ascending=button.dataset.direction!=='asc';rows.sort((a,b)=>{const x=Number(a.cells[col].dataset.value||-1),y=Number(b.cells[col].dataset.value||-1);return (x-y)*(ascending?1:-1)});rows.forEach(row=>body.append(row));button.dataset.direction=ascending?'asc':'desc';document.querySelectorAll('.sort-button span').forEach(s=>s.textContent='↕');button.querySelector('span').textContent=ascending?'↑':'↓'}));
</script>
<?php require __DIR__ . '/includes/footer.php'; ?>
